def canon(sh):
    pts=np.array(sh)
    variants=[]
    for refl in [False,True]:
      p=pts.copy()
      if refl: p[:,1]*=-1
      for k in range(4):
        q=np.rot90(p,k,axes=(0,1)) if False else None
        # coordinate rotation manually
        r=p.copy()
        for _ in range(k): r=np.stack([r[:,1],-r[:,0]],axis=1)
        r-=r.min(axis=0)
        variants.append(tuple(sorted(map(tuple,r.tolist()))))
    return min(variants)
